using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Collections;using System.Collections.Generic;using System.Reflection;using System.Web.Script.Serialization;
namespace PZ3D {static class VersionListConcurrency {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=2097152};static int checks;static void Check(bool value,string label){checks++;if(!value)throw new Exception("FAIL "+label);}static void Put(string path,string value){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,value,new UTF8Encoding(false));}
 static string Game(string root,string name){string path=Path.Combine(root,name);Put(Path.Combine(path,"ProjectZomboid64.exe"),"owned fixture, never execute");Put(Path.Combine(path,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");Put(Path.Combine(path,"version.txt"),"42.21.0");Put(Path.Combine(path,"payload.bin"),new string('x',8192));return path;}
 sealed class Reply {internal object Value;internal Exception Error;}static Reply Attempt(Func<object> action){try{return new Reply{Value=action()};}catch(Exception error){return new Reply{Error=error};}}
 static Dictionary<string,object> P(params string[] values){var p=new Dictionary<string,object>();for(int n=0;n<values.Length;n+=2)p.Add(values[n],values[n+1]);return p;}static Dictionary<string,object> D(object value){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(value));}
 static void Coherent(object value){var row=D(value);var versions=((IEnumerable)row["versions"]).Cast<Dictionary<string,object>>().ToArray();Check(versions.Count(v=>(bool)v["selected"])==1&&versions.Single(v=>(bool)v["selected"])["id"].Equals(row["selectedId"]),"selected ID and row flags come from one coherent document");}
 static object Call(ModernController c,string action,Dictionary<string,object> p){return c.CaptureRequest(action,p)();}
 public static int Main(string[] args){try{if(args.Length==3&&args[0]=="--select-loop"){string folder=Path.GetFullPath(args[1]);var shared=new VersionLibrary(Path.Combine(folder,"data"),Path.Combine(folder,"game"),Path.Combine(folder,"user"));File.WriteAllText(Path.Combine(folder,"publisher-ready.flag"),"ready");for(int n=0;n<40;n++){shared.Select(n%2==0?args[2]:"steam");Thread.Sleep(3);}Console.WriteLine("PASS separate-process version publication");return 0;}Run(Path.GetFullPath(args[0]));VersionLibraryTests.Run();Console.WriteLine("PASS VersionListConcurrency "+checks+" targeted checks; no game process or foreground input");return 0;}catch(Exception error){Console.WriteLine("Completed checks before failure: "+checks);Console.WriteLine(error);return 1;}}
 static void Run(string root){Directory.CreateDirectory(root);string game=Game(root,"game"),other=Game(root,"imported"),third=Game(root,"third"),user=Path.Combine(root,"user"),data=Path.Combine(root,"data"),target=Path.Combine(root,"preserved"),index=Path.Combine(data,"version-library.json");Directory.CreateDirectory(user);var library=new VersionLibrary(data,game,user);var imported=library.Import(other,"已有版本");byte[] original=File.ReadAllBytes(index);ManualResetEventSlim entered=new ManualResetEventSlim(),release=new ManualResetEventSlim();
 using(var controller=new ModernController(game,user,data,true)){
  controller.Progress=(value,text)=>{if(text.StartsWith("正在保存版本",StringComparison.Ordinal)){entered.Set();if(!release.Wait(15000))throw new TimeoutException("owned copy progress hold timed out");}};
  var writer=Task.Run(()=>Attempt(()=>Call(controller,"versionPreserve",P("destination",target,"name","保存版本"))));
  try{Check(entered.Wait(5000),"real root version writer reached its actual copy-progress stage");Check(controller.Busy,"root writer owns the global busy lane while real copy is held");var cancellation=(CancellationTokenSource)typeof(ModernController).GetField("cancel",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(controller);
   var read=Task.Run(()=>Attempt(()=>Call(controller,"versionList",P())));Check(read.Wait(1500),"version read completes while actual copy/publish writer remains held");Check(read.Result.Error==null,"version read is independent of global busy: "+(read.Result.Error==null?"":read.Result.Error.Message));Coherent(read.Result.Value);Check(original.SequenceEqual(File.ReadAllBytes(index)),"held writer and independent read have not changed published metadata");Check(controller.Busy&&!writer.IsCompleted,"read cannot release the writer's occupation");Check(ReferenceEquals(cancellation,typeof(ModernController).GetField("cancel",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(controller))&&!cancellation.IsCancellationRequested,"read does not replace or cancel the writer CTS");
   var reads=Enumerable.Range(0,8).Select(_=>Task.Run(()=>Attempt(()=>Call(controller,"versionList",P())))).ToArray();Check(Task.WaitAll(reads,2000),"parallel page readers complete without a query lock");foreach(var item in reads){Check(item.Result.Error==null,"every concurrent version read succeeds");Coherent(item.Result.Value);}Check(Attempt(()=>Call(controller,"versionImport",P("path",third,"name","conflict"))).Error!=null,"true conflicting version writer stays blocked");Check(Attempt(()=>Call(controller,"versionList",P("path",third))).Error!=null,"read payload validation remains strict while busy");
  }finally{release.Set();Check(writer.Wait(5000),"owned writer finishes after release");}Check(writer.Result.Error==null,"own copy writer commits successfully");Check(!controller.Busy,"writer releases its occupation");Coherent(Call(controller,"versionList",P()));Check(File.ReadAllText(Path.Combine(target,"payload.bin"))==new string('x',8192),"actual copied file bytes are exact");
  var open=typeof(VersionLibrary).GetMethod("OpenMetadataRead",BindingFlags.Static|BindingFlags.NonPublic);Check(open!=null,"version metadata reads use the replace-compatible production entry");using(var handle=(FileStream)open.Invoke(null,new object[]{index})){byte[] before=new byte[handle.Length];handle.Read(before,0,before.Length);var publishing=Task.Run(()=>library.Import(third,"并发发布"));Check(publishing.Wait(2000),"atomic version publication succeeds while a production read handle is open");handle.Position=0;byte[] retained=new byte[handle.Length];handle.Read(retained,0,retained.Length);Check(before.SequenceEqual(retained),"open reader keeps the old coherent metadata bytes after replacement");}Coherent(Call(controller,"versionList",P()));
  var selecting=Task.Run(()=>{for(int n=0;n<12;n++)library.Select(n%2==0?imported.Id:"steam");});for(int n=0;n<12;n++)Coherent(Call(controller,"versionList",P()));Check(selecting.Wait(3000),"real version selection writes coexist with read snapshots");
  using(var oldHandle=(FileStream)open.Invoke(null,new object[]{index})){byte[] oldBytes=new byte[oldHandle.Length];oldHandle.Read(oldBytes,0,oldBytes.Length);var processInfo=new System.Diagnostics.ProcessStartInfo{FileName=System.Diagnostics.Process.GetCurrentProcess().MainModule.FileName,Arguments="--select-loop \""+root+"\" "+imported.Id,WorkingDirectory=root,UseShellExecute=false,CreateNoWindow=true,WindowStyle=System.Diagnostics.ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true};using(var publisher=System.Diagnostics.Process.Start(processInfo)){Check(SpinWait.SpinUntil(()=>File.Exists(Path.Combine(root,"publisher-ready.flag"))||publisher.HasExited,3000),"separate native publisher starts");int reads=0;while(!publisher.HasExited&&reads<200){Coherent(Call(controller,"versionList",P()));reads++;}Check(reads>0,"actual native reads overlap separate-process metadata publication");Check(publisher.WaitForExit(3000),"separate native publisher completes");string standard=publisher.StandardOutput.ReadToEnd(),error=publisher.StandardError.ReadToEnd();Check(publisher.ExitCode==0&&standard.Contains("PASS separate-process"),"separate native publisher succeeds: "+error);}oldHandle.Position=0;byte[] afterPublish=new byte[oldHandle.Length];oldHandle.Read(afterPublish,0,afterPublish.Length);Check(oldBytes.SequenceEqual(afterPublish),"held production Read|Delete handle survives actual separate-process publications with old bytes exact");}Coherent(Call(controller,"versionList",P()));
  byte[] valid=File.ReadAllBytes(index);try{File.WriteAllBytes(index,new byte[1048577]);Check(Attempt(()=>Call(controller,"versionList",P())).Error!=null,"metadata size bound still rejects oversized publication");Check(new FileInfo(index).Length==1048577,"oversized metadata is preserved rather than repaired");Put(index,"{");Check(Attempt(()=>Call(controller,"versionList",P())).Error!=null,"corrupt metadata is not hidden or reset");Check(File.ReadAllText(index)=="{","failed read leaves corrupt bytes untouched");var document=D(Json.DeserializeObject(Encoding.UTF8.GetString(valid)));document["SelectedId"]=Guid.NewGuid().ToString("N");Put(index,Json.Serialize(document));Check(Attempt(()=>Call(controller,"versionList",P())).Error!=null,"versionList retains strict missing selected-version validation");}finally{File.WriteAllBytes(index,valid);}
  var policy=ModernHostPolicy.Validate("https://orange.local/index.html",Json.Serialize(new{id="versions",action="versionList",payload=P()}));Check(ModernHostPolicy.IsNativeRead("versionList",P()),"host classifies only this existing action as a read");Check(!ModernHostPolicy.IsNativeRead("versionChooseImport",P("name","owned")),"folder chooser/import does not become capture read");bool denied=false;try{CoreHealthStartup.ValidateAction("versionChooseImport",P("name","owned"),new CoreUpdateTaskInfo{State="PendingHealth"});}catch{denied=true;}Check(denied,"pending health still refuses version mutation");
  controller.Cancel();var cancelled=(CancellationTokenSource)typeof(ModernController).GetField("cancel",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(controller);Coherent(Call(controller,"versionList",P()));Check(cancelled.IsCancellationRequested&&ReferenceEquals(cancelled,typeof(ModernController).GetField("cancel",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(controller)),"read after cancellation is usable without changing cancelled CTS");
 }
 using(var disposed=new ModernController(game,user,Path.Combine(root,"disposed-data"),true)){disposed.Dispose();Check(Attempt(()=>Call(disposed,"versionList",P())).Error is ObjectDisposedException,"disposed version reads still fail");}
 Console.WriteLine("Retained owned fixture: "+root);
 }
}}
